(function(){var t,n,e=document.getElementById("project-board");if(!e)return;t=e.querySelectorAll("[data-filter]"),n=e.querySelectorAll("[data-tags]"),t.forEach(function(e){e.addEventListener("click",function(){var s=e.getAttribute("data-filter");t.forEach(function(t){t.setAttribute("aria-pressed",t===e?"true":"false")}),n.forEach(function(e){var t=(e.getAttribute("data-tags")||"").split("|");e.hidden=s!=="*"&&t.indexOf(s)===-1})})})})()